// Coding-owned generation: never invoke the multi-application entry generator here.
import { resolve } from "node:path";
import { z } from "zod";
import { kernelAgentInputs, kernelAgentOutputs } from "./kernel-schema";

type JsonSchema = boolean | z.core.JSONSchema.JSONSchema;

/** Render parsed DTOs, including defaults and recursive JSON, from the contract schemas. */
function schemaDeclaration(schema: z.ZodType, name: string): string[] {
  const json: JsonSchema = z.toJSONSchema(schema, { io: "output" });
  const definitions = typeof json === "object" ? Object.entries(json.$defs ?? {}) : [];
  const references = new Map<string, string>([["#", name], ...definitions.map(([key], index) => [
    `#/$defs/${key.replace(/~/g, "~0").replace(/\//g, "~1")}`, `${name}Definition${index}`,
  ] as const)]);
  function typeOf(value: JsonSchema): string {
    if (value === false) return "never";
    if (value === true) throw new Error(`Unconstrained Coding declaration in ${name}`);
    if (value.$ref) {
      const reference = references.get(value.$ref);
      if (!reference) throw new Error(`Unsupported Coding declaration reference: ${value.$ref}`);
      return reference;
    }
    if ("const" in value) return JSON.stringify(value.const);
    if (value.enum) return value.enum.map(item => JSON.stringify(item)).join(" | ") || "never";
    for (const [parts, separator] of [[value.anyOf, " | "], [value.oneOf, " | "], [value.allOf, " & "]] as const) {
      if (parts) return `(${parts.map(typeOf).join(separator)})`;
    }
    return structuredType(value);
  }
  function structuredType(value: Exclude<JsonSchema, boolean>): string {
    switch (value.type) {
      case "string": return "string";
      case "number": case "integer": return "number";
      case "boolean": return "boolean";
      case "null": return "null";
      case "array": {
        if (value.items === undefined || Array.isArray(value.items)) throw new Error(`Unsupported Coding array items in ${name}`);
        return `Array<${typeOf(value.items)}>`;
      }
      case "object": {
        const fields = Object.entries(value.properties ?? {}).map(([key, field]) =>
          `${JSON.stringify(key)}${value.required?.includes(key) ? "" : "?"}: ${typeOf(field)}`);
        if (value.additionalProperties) fields.push(`[key: string]: ${typeOf(value.additionalProperties)}`);
        return `{ ${fields.join("; ")} }`;
      }
      default: throw new Error(`Unsupported Coding declaration schema in ${name}: ${JSON.stringify(value)}`);
    }
  }
  return [
    ...definitions.map(([, value], index) => `type ${name}Definition${index} = ${typeOf(value)};`),
    `type ${name} = ${typeOf(json)};`,
  ];
}

/** Like the entry DTO generator, expose the validators' parsed types without workspace imports. */
export function kernelContractDeclarations(): string {
  const lines = [
    "// Generated by Coding build-kernel.ts from @chrona/contracts/steward. Do not edit.",
    "type ContractSchema<T> = { parse(value: unknown): T; safeParse(value: unknown): { success: true; data: T } | { success: false; error: { message: string; issues: { message: string; path: PropertyKey[] }[] } } };",
  ];
  for (const [group, schemas] of Object.entries({ kernelAgentInputs, kernelAgentOutputs })) {
    const fields = Object.entries(schemas).map(([key, schema]) => {
      const name = `${group[0]!.toUpperCase()}${group.slice(1)}${key[0]!.toUpperCase()}${key.slice(1)}`;
      lines.push(...schemaDeclaration(schema, name));
      return `  ${JSON.stringify(key)}: ContractSchema<${name}>;`;
    });
    lines.push(`export declare const ${group}: {\n${fields.join("\n")}\n};`);
  }
  return lines.join("\n") + "\n";
}

if (import.meta.main) {
  const root = import.meta.dir;
  const result = await Bun.build({ entrypoints: [resolve(root, "kernel-schema.ts")], target: "bun", minify: true });
  if (!result.success) throw new AggregateError(result.logs, "Coding kernel schemas failed to build");
  await Bun.write(resolve(root, "kernel-contract.js"), "// Generated by Coding build-kernel.ts.\n" + await result.outputs[0]!.text());
  await Bun.write(resolve(root, "kernel-contract.d.ts"), kernelContractDeclarations());
  // Keep this distributed source current even though Coding's entry uses client.ts.
  const client = "// Generated by build/entry-conversations.ts from entry-app/kernel-client.ts.\n"
    + await Bun.file(resolve(root, "../../entry-app/kernel-client.ts")).text();
  if (await Bun.file(resolve(root, "kernel-client.ts")).text() !== client) await Bun.write(resolve(root, "kernel-client.ts"), client);
}
